import {solutionAccount,reactingAccount,gasMassAccount,gasRatioVolume,molarTasks,reactingTasks,gasTasks} from './volume-models.js?v=20261023-physicscomplete01';
import {showVolume} from './volume-scenes.js?v=20261023-physicscomplete01';
const input=(id,label,v='')=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any" value="${v}">`;
export function mountVolumeWidget(l,p,root,{save,done,feedback}){
 const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={},kind=l.widget.slice(7),molar=kind==='molar-concentration',reacting=kind==='reacting-solutions',t=(molar?molarTasks:reacting?reactingTasks:gasTasks)[i],$=s=>root.querySelector(s);let result,fields,prompt;
 if(molar){result=solutionAccount(t.c,t.cm3,t.mr);fields=[['amount','Solute amount / mol',.000001],['mass','Solute mass / g',.001]];prompt=`${t.solute}: ${t.c} mol/dm³, total solution volume ${t.cm3} cm³, relative formula mass ${t.mr}. Calculate amount and mass.`;}
 else if(reacting){result=reactingAccount(t.c,t.knownCm3,t.unknownCm3,t.knownCoeff,t.unknownCoeff);fields=[['known',t.known+' amount / mol',.000001],['unknown',t.unknown+' amount / mol',.000001],['concentration',t.unknown+' concentration / mol/dm³',.001]];prompt=`${t.equation}. ${t.knownCm3} cm³ ${t.known} at ${t.c} mol/dm³ reacts completely with ${t.unknownCm3} cm³ ${t.unknown}. Find the unknown concentration using the equation ratio.`;}
 else{result=t.kind==='mass'?gasMassAccount(t.mass,t.mr):{amount:t.volume/24,volume:gasRatioVolume(t.volume,t.from,t.to)};fields=[['amount','Given gas amount / mol',.000001],['volume','Required gas volume / dm³',.001]];prompt=t.kind==='mass'?`${t.mass} g ${t.gas}, relative formula mass ${t.mr}. Find its amount and volume at RTP (20°C, 1 atmosphere).`:`${t.equation}. Start with ${t.volume} dm³ ${t.given} at RTP. N₂ is in excess. Calculate the given H₂ amount and maximum ${t.target} volume at the same conditions, assuming complete conversion.`;}
 root.innerHTML=`<p><b>Case ${i+1} / 3</b></p><p>${prompt}</p>`+fields.map(([k,label])=>input('volume-'+k,label,a[k])).join('')+`<button class="secondary" id="checkVolume">Check the account</button><button class="secondary" id="nextVolume">Next case →</button><p id="volumeProgress">${w.passed.length} / 3 cases correct</p>`;
 fields.forEach(([k])=>$('#volume-'+k).oninput=e=>{a[k]=e.target.value;save();});showVolume(kind,t,w.passed.includes(i)?result:null);
 $('#checkVolume').onclick=()=>{const ok=fields.every(([k,label,tol])=>a[k]!==undefined&&a[k]!==''&&Number.isFinite(Number(a[k]))&&Math.abs(Number(a[k])-result[k])<=tol);if(!ok){feedback(molar?'Convert cm³ to dm³ by dividing by1000. Use n=cV, then m=nMᵣ.':reacting?'Known amount=c×known volume in dm³. Apply unknown/known coefficients, then divide by the UNKNOWN solution volume in dm³.':'For mass data use n=m/Mᵣ then V=24n at RTP. For gas ratios multiply given volume by required/given coefficients at equal conditions.',true);return;}
 if(!w.passed.includes(i))w.passed.push(i);save();showVolume(kind,t,result);$('#volumeProgress').textContent=w.passed.length+' / 3 cases correct';feedback('Correct. The account now shows the calculated amounts and result with units.');if(w.passed.length===3){p.widgetDone=true;save();done();}
 };$('#nextVolume').onclick=()=>{w.task=(i+1)%3;save();mountVolumeWidget(l,p,root,{save,done,feedback});};
}
